import java.util.*; public class Week05Problem03{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();if(n<=0)return;int lo=Integer.MAX_VALUE,hi=Integer.MIN_VALUE;for(int i=0;i<n;i++){int v=s.nextInt();lo=Math.min(lo,v);hi=Math.max(hi,v);}System.out.println("Minimum: "+lo);System.out.println("Maximum: "+hi);System.out.println("Spread: "+((long)hi-lo));}}